from typing import Any, Optional
from fastapi import Request
from fastapi.responses import JSONResponse


class AppError(Exception):
    def __init__(
        self,
        message: str,
        error_code: str = "INTERNAL_ERROR",
        status_code: int = 500,
        details: Optional[Any] = None,
    ):
        super().__init__(message)
        self.message = message
        self.error_code = error_code
        self.status_code = status_code
        self.details = details


class NotFoundError(AppError):
    def __init__(self, message: str = "Resource not found", error_code: str = "NOT_FOUND"):
        super().__init__(message=message, error_code=error_code, status_code=404)


class ValidationError(AppError):
    def __init__(self, message: str = "Validation failed", error_code: str = "VALIDATION_ERROR"):
        super().__init__(message=message, error_code=error_code, status_code=400)


class ProviderUnavailableError(AppError):
    def __init__(
        self,
        message: str = "Provider unavailable",
        error_code: str = "PROVIDER_UNAVAILABLE",
    ):
        super().__init__(message=message, error_code=error_code, status_code=502)


class InternalError(AppError):
    def __init__(
        self, message: str = "Internal server error", error_code: str = "INTERNAL_ERROR"
    ):
        super().__init__(message=message, error_code=error_code, status_code=500)


async def app_error_exception_handler(request: Request, exc: AppError) -> JSONResponse:
    request_id = getattr(request.state, "request_id", None)
    return JSONResponse(
        status_code=exc.status_code,
        content={
            "error_code": exc.error_code,
            "message": exc.message,
            "request_id": request_id,
        },
    )

from typing import Generator
from sqlalchemy.orm import Session

from packages.shared.config import Settings, get_settings
from packages.shared.db import SessionLocal


def get_db() -> Generator[Session, None, None]:
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()


def get_settings_dep() -> Settings:
    return get_settings()

