let input = '';
for await (const chunk of process.stdin) input += chunk;
const request = JSON.parse(input);

try {
  let url = `${request.baseUrl}/chat/completions`;
  let headers = {
    'Content-Type': 'application/json'
  };

  if (request.provider === 'anthropic') {
    url = 'https://api.anthropic.com/v1/messages';
    headers['x-api-key'] = request.apiKey;
    headers['anthropic-version'] = '2023-06-01';
  } else if (request.provider === 'openai') {
    headers['Authorization'] = `Bearer ${request.apiKey}`;
  } else {
    // Ollama
    if (!url.includes('/v1/')) {
       url = `${request.baseUrl}/api/chat`;
    }
  }

  let body;
  if (request.provider === 'anthropic') {
    body = JSON.stringify({
      model: request.model,
      system: request.system,
      messages: [{role: 'user', content: request.prompt}],
      max_tokens: 2800
    });
  } else {
    body = JSON.stringify({
      model: request.model,
      messages: [
        {role: 'system', content: request.system},
        {role: 'user', content: request.prompt}
      ]
    });
  }

  const response = await fetch(url, {
    method: 'POST',
    headers,
    body
  });

  if (!response.ok) {
    throw new Error(`HTTP ${response.status}: ${await response.text()}`);
  }

  const data = await response.json();
  let text = '';

  if (request.provider === 'anthropic') {
    text = data.content?.[0]?.text || '';
  } else {
    // OpenAI / Ollama OpenAI compatibility
    text = data.choices?.[0]?.message?.content || data.message?.content || '';
  }

  if (!text) throw new Error('No text generated');

  process.stdout.write(JSON.stringify({text}));

} catch (error) {
  process.stdout.write(JSON.stringify({error: 'GENERATION_FAILED'}));
  process.exitCode = 1;
}

